    },
    {
      "name": "jam_time",
      "value": "5.0",
      "units": "s",
      "narrative_section": "3. ST10 — Pallet conveyor"
    }
  ],
  "steps": [
    {
      "name": "Conveyor Running",
      "entry": "Auto mode selected (SS-0003, X2) AND no ST10 fault active (M199 OFF)",
      "exit": "Auto mode lost OR ST10 fault/stop occurs (M199 ON)"
    },
    {
      "name": "Stopper Released (Pallet Release)",
      "entry": "Release request rising edge (RQ-1005, X14)",
      "exit": "Release pulse timer elapsed (T11, 2.0 s)"
    }
  ],
  "interlocks": [
    {
      "cause": "Motor overload (MOL-1001, X13 lost) or E-stop chain lost (ES-0001, X0 lost)",
      "effect": "Conveyor motor M-1001 (Y10) stops immediately via ST10 fault summary (M199)"
    },
    {
      "cause": "ST10 fault summary active (M199 ON) or not in auto mode (X2 OFF)",
      "effect": "Inhibits conveyor motor M-1001 (Y10)"
    },
    {
      "cause": "Pallet in position (PE-1001, X10)",
      "effect": "Reports pallet in position (M100) to ST20"
    }
  ],
  "alarms": [
    {
      "name": "Motor Overload Alarm",
      "condition": "Motor overload input lost (MOL-1001, X13 OFF)",
      "action": "Sets M191; sets ST10 fault summary M199; stops conveyor motor Y10 immediately"
    },
    {
      "name": "Jam Alarm",
      "condition": "Entry photo-eye PE-1002 stays blocked for more than 5.0 s while conveyor runs",
      "action": "Stops conveyor and raises jam alarm (M190) until reset"
    }
  ],
  "conflicts": [
    {
      "item": "jam_time implementation",
      "narrative_says": "If entry photo-eye PE-1002 stays blocked for more than 5.0 s while conveyor runs, raise jam alarm",
      "parameter_sheet_says": "jam_time = 5.0 s on T10",
      "program_says": "T10 and the entry photo-eye detection logic are completely missing from the program",
      "authoritative": "parameter_sheet"
    }
  ]
}
